script:
// Sales Order — CS Client Script
// BRD §4 (Order Execution) + §5 (Sales Order Processing) v1.1
// FR-4-01 discount gate, FR-4-02 credit hold, CR-01 per-line dates,
// CR-04 Save & Create DN, BR-SO-01 RC block, FR-5-02 auto-GST

frappe.ui.form.on('Sales Order', {

    refresh(frm) {
        render_cs_status_banner(frm);
        add_save_and_create_dn_button(frm);
        set_rc_discount_lock(frm);
        highlight_delivery_dates(frm);
    },

    customer(frm) {
        if (!frm.doc.customer) return;
        // Auto-fill RC flag from Customer master
        frappe.db.get_value('Customer', frm.doc.customer, ['cs_rc_customer', 'cs_po_mandatory'],
            (r) => {
                if (!r) return;
                frm.set_value('cs_rc_customer', r.cs_rc_customer);
                set_rc_discount_lock(frm);
                if (r.cs_po_mandatory) {
                    frm.set_df_property('cs_po_copy', 'reqd', 1);
                    frappe.show_alert({
                        message: 'PO copy upload is mandatory for this customer (BR-SO-02)',
                        indicator: 'orange'
                    }, 5);
                }
            }
        );
    },

    cs_order_type(frm) {
        // CR-01: per-line delivery date mandatory for Open orders
        const is_open = frm.doc.cs_order_type === 'Open (Phased Delivery)';
        frm.fields_dict.items.grid.update_docfield_property(
            'cs_required_delivery_date', 'reqd', is_open ? 1 : 0
        );
        if (is_open) {
            frappe.show_alert({
                message: 'Open order: each line item must have a Required Delivery Date (v1.1 CR-01)',
                indicator: 'blue'
            }, 6);
        }
    },

    validate(frm) {
        check_discount_threshold(frm);
        check_po_mandatory(frm);
        check_per_line_dates(frm);
    }
});

// ── Per-line delivery date changes ──────────────────────────────────────────
frappe.ui.form.on('Sales Order Item', {
    cs_required_delivery_date(frm, cdt, cdn) {
        const row = locals[cdt][cdn];
        if (row.cs_required_delivery_date && row.qty && !row.actual_qty) {
            // Warn if date is set but stock is zero — will trigger backorder (CR-02)
            frappe.db.get_value('Bin',
                {item_code: row.item_code, warehouse: frm.doc.set_warehouse},
                'actual_qty',
                (r) => {
                    const avail = (r && r.actual_qty) || 0;
                    if (avail < (row.qty || 0)) {
                        frappe.show_alert({
                            message: `${row.item_code}: Only ${avail} in stock. ` +
                                     `Future delivery date accepted — backorder/KMPO will be triggered on save. (v1.1 CR-02)`,
                            indicator: 'orange'
                        }, 7);
                    }
                }
            );
        }
    }
});

// ── Discount threshold check (FR-4-01, BR-OE-01) ────────────────────────────
function check_discount_threshold(frm) {
    if (!frm.doc.items) return;
    const threshold = frm.doc.cs_discount_threshold || 10;
    const max_disc  = Math.max(...frm.doc.items.map(i => i.discount_percentage || 0));
    if (max_disc > threshold &&
            frm.doc.cs_discount_approval_status !== 'Approved') {
        frappe.validated = false;
        frappe.msgprint({
            title: 'Discount Approval Required',
            message: `Maximum discount ${max_disc.toFixed(1)}% exceeds threshold ${threshold}%. ` +
                     `Sales Head approval is required before this order can proceed. (BR-OE-01)\n\n` +
                     `Status will be set to "Discount Approval — Sales Head".`,
            indicator: 'orange'
        });
    }
}

// ── PO mandatory check (BR-SO-02) ───────────────────────────────────────────
function check_po_mandatory(frm) {
    if (frm.doc.cs_rc_customer && !frm.doc.po_no) {
        frappe.validated = false;
        frappe.msgprint('PO Number is mandatory for this customer (BR-SO-02)');
    }
}

// ── Per-line date check for Open orders (CR-01) ─────────────────────────────
function check_per_line_dates(frm) {
    if (frm.doc.cs_order_type !== 'Open (Phased Delivery)') return;
    const missing = (frm.doc.items || []).filter(i => !i.cs_required_delivery_date);
    if (missing.length) {
        frappe.validated = false;
        frappe.msgprint({
            title: 'Missing Required Delivery Dates',
            message: `Open orders require a Required Delivery Date on every line item (v1.1 CR-01).\n` +
                     `Missing on: ${missing.map(i => i.item_code).join(', ')}`,
            indicator: 'red'
        });
    }
}

// ── RC customer: lock discount fields (BR-SO-01) ────────────────────────────
function set_rc_discount_lock(frm) {
    if (!frm.doc.cs_rc_customer) return;
    frm.fields_dict.items.grid.update_docfield_property('discount_percentage', 'read_only', 1);
    frm.fields_dict.items.grid.update_docfield_property('discount_amount',     'read_only', 1);
    if (!frm._rc_banner) {
        frm._rc_banner = frm.set_intro(
            'Rate Contract customer — discounts are blocked on all line items. (BR-SO-01)', 'orange');
    }
}

// ── Status banner (v1.1 CR-06: Discount Approval — Sales Head with elapsed time) ─
function render_cs_status_banner(frm) {
    if (frm.is_new()) return;

    const status = frm.doc.cs_discount_approval_status;
    const credit = frm.doc.cs_credit_hold_status;

    let html = '';

    if (status === 'Discount Approval — Sales Head') {
        const created = moment(frm.doc.creation);
        const elapsed = moment().diff(created, 'hours', true).toFixed(1);
        html += [
            '<div style="background:#FEF9E7;border:2px solid #F39C12;border-radius:6px;',
            'padding:12px 16px;margin-bottom:10px;display:flex;justify-content:space-between;align-items:center;">',
            '<div>',
            '<span style="font-weight:700;color:#7D5005;font-size:13px;">',
            '⏳ Discount Approval — Sales Head</span>',
            '<span style="font-size:12px;color:#7D5005;margin-left:12px;">',
            'Approver: <strong>' + (frm.doc.cs_discount_approved_by || 'Sales Head') + '</strong>',
            '&nbsp;·&nbsp; Waiting: <strong>' + elapsed + 'h</strong>',
            '&nbsp;·&nbsp; Max discount: <strong>' +
            Math.max(...(frm.doc.items||[]).map(i=>i.discount_percentage||0)).toFixed(1) + '%</strong>',
            '</span></div>',
            '<span style="font-size:11px;color:#7D5005;">BR-OE-01 · v1.1 CR-06</span>',
            '</div>'
        ].join('');
    }

    if (credit === 'On Hold') {
        html += [
            '<div style="background:#FDEDEC;border:2px solid #C0392B;border-radius:6px;',
            'padding:12px 16px;margin-bottom:10px;">',
            '<span style="font-weight:700;color:#C0392B;font-size:13px;">🔴 Credit Hold</span>',
            '<span style="font-size:12px;color:#922B21;margin-left:12px;">',
            frm.doc.cs_credit_hold_reason || 'Finance release required.',
            '</span></div>'
        ].join('');
    }

    if (status === 'Approved' && credit === 'Clear') {
        html = '<div style="background:#E9F7EF;border:1px solid #27AE60;border-radius:6px;' +
               'padding:10px 16px;margin-bottom:10px;font-size:13px;color:#1E8449;">' +
               '✅ Discount approved · Credit clear · Ready to proceed</div>';
    }

    if (html) {
        if (!frm._cs_banner) {
            frm._cs_banner = $(html).prependTo(frm.fields_dict['cs_section'].$wrapper);
        } else {
            frm._cs_banner.replaceWith($(html));
        }
    }
}

// ── Save & Create Delivery Note button (v1.1 CR-04) ─────────────────────────
function add_save_and_create_dn_button(frm) {
    if (frm.is_new() || frm.doc.docstatus !== 1) return;
    if (frm.doc.cs_discount_approval_status === 'Discount Approval — Sales Head') return;
    if (frm.doc.cs_credit_hold_status === 'On Hold') return;

    frm.add_custom_button('Save & Create Delivery Note', () => {
        frappe.confirm(
            'Create a Delivery Note from this Sales Order and route it to the Warehouse queue?',
            () => {
                frappe.call({
                    method: 'erpnext.selling.doctype.sales_order.sales_order.make_delivery_note',
                    args: {source_name: frm.doc.name},
                    callback(r) {
                        if (r.message) {
                            const dn = frappe.model.sync(r.message);
                            frappe.set_route('Form', 'Delivery Note', dn[0].name);
                            frappe.show_alert({
                                message: 'Delivery Note ' + dn[0].name + ' created and routed to Warehouse',
                                indicator: 'green'
                            }, 7);
                        }
                    }
                });
            }
        );
    }, 'Create').addClass('btn-primary');
}

// ── Highlight missing delivery dates in items table ──────────────────────────
function highlight_delivery_dates(frm) {
    if (frm.doc.cs_order_type !== 'Open (Phased Delivery)') return;
    (frm.doc.items || []).forEach((row, idx) => {
        if (!row.cs_required_delivery_date) {
            const grid_row = frm.fields_dict.items.grid.grid_rows[idx];
            if (grid_row) {
                grid_row.row.css('background', '#FFF9F0');
            }
        }
    });
}
